extern crate file_native_incremental;
use file_native_incremental::io;use std::{fs,path::Path};
fn main()->io::Result<()>{let root=Path::new("/private/tmp/file-native-q-macos-20261019/native-fileops");fs::create_dir_all(root)?;let mut m=io::Metrics::default();let stage=root.join("owned-stage");let dest=root.join("immutable");io::write_new(&stage,b"exact",&mut m)?;io::install_original(&stage,&dest,&io::digest(b"exact"),&mut m)?;assert!(!stage.exists());assert_eq!(fs::read(&dest)?,b"exact");io::write_new(&stage,b"exact",&mut m)?;io::install_original(&stage,&dest,&io::digest(b"exact"),&mut m)?;assert!(stage.exists());assert!(io::install_original(&stage,&dest,&io::digest(b"wrong"),&mut m).is_err());assert_eq!(fs::read(&dest)?,b"exact");let from=root.join("replace-stage");io::write_new(&from,b"replacement",&mut m)?;io::replace(&from,&dest,&mut m)?;io::sync_dir(root,&mut m)?;assert_eq!(fs::read(&dest)?,b"replacement");assert!(m.directory_syncs>0);assert_eq!(m.unsupported_directory_syncs,0);println!("immutable-new/exact-winner/corrupt-winner-refusal/replacement/directory-sync passed; directory_syncs={}",m.directory_syncs);Ok(())}
